using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using System.Text.Json;
using Xunit;

namespace MyApp.Coach.Eval;

public class EvalTests
{
    private static readonly string ScenariosPath =
        Path.Combine(AppContext.BaseDirectory, "Scenarios");

    [Theory]
    [MemberData(nameof(GetScenarios))]
    public async Task Quality_MeetsThreshold(string scenarioFile)
    {
        var scenario = await LoadScenario(scenarioFile);
        var client = CreateChatClient();

        var response = await client.GetResponseAsync(scenario.Messages);

        var evaluator = new RelevanceEvaluator();
        var result = await evaluator.EvaluateAsync(
            scenario.Messages,
            response,
            CreateJudgeChatClient());

        Assert.All(result.Metrics, m =>
            Assert.True(m.Value?.NumericValue >= 3.0,
                $"Metric '{m.Key}' scored {m.Value?.NumericValue}, expected >= 3.0"));
    }

    [Theory]
    [MemberData(nameof(GetScenarios))]
    public async Task Compare_CandidateNotWorse(string scenarioFile)
    {
        var scenario = await LoadScenario(scenarioFile);

        var baseline = CreateChatClient(tag: "baseline");
        var candidate = CreateChatClient(tag: "candidate");

        var baselineResponse = await baseline.GetResponseAsync(scenario.Messages);
        var candidateResponse = await candidate.GetResponseAsync(scenario.Messages);

        var evaluator = new RelevanceEvaluator();
        var judge = CreateJudgeChatClient();

        var baselineResult = await evaluator.EvaluateAsync(
            scenario.Messages, baselineResponse, judge);
        var candidateResult = await evaluator.EvaluateAsync(
            scenario.Messages, candidateResponse, judge);

        var baselineScore = baselineResult.Metrics.Values
            .Average(m => m.NumericValue ?? 0);
        var candidateScore = candidateResult.Metrics.Values
            .Average(m => m.NumericValue ?? 0);

        Assert.True(candidateScore >= baselineScore - 0.5,
            $"Candidate ({candidateScore:F2}) regressed vs baseline ({baselineScore:F2})");
    }

    public static IEnumerable<object[]> GetScenarios()
    {
        if (!Directory.Exists(ScenariosPath))
            yield break;

        foreach (var file in Directory.GetFiles(ScenariosPath, "*.json"))
            yield return [Path.GetFileName(file)];
    }

    private static async Task<Scenario> LoadScenario(string fileName)
    {
        var path = Path.Combine(ScenariosPath, fileName);
        var json = await File.ReadAllTextAsync(path);
        return JsonSerializer.Deserialize<Scenario>(json)!;
    }

    private static IChatClient CreateChatClient(string? tag = null)
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://localhost";
        var model = tag == "baseline"
            ? Environment.GetEnvironmentVariable("EVAL_BASELINE_MODEL") ?? "gpt-4o-mini"
            : Environment.GetEnvironmentVariable("EVAL_CANDIDATE_MODEL") ?? "gpt-4o-mini";

        return new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new Azure.Identity.DefaultAzureCredential())
            .GetChatClient(model)
            .AsIChatClient();
    }

    private static IChatClient CreateJudgeChatClient() => CreateChatClient();
}

public record Scenario(List<ChatMessage> Messages, string? ExpectedIntent = null);

